// CloudWatch Synthetics canary. Fails unless HDBResale_Core /Health returns Status = OK,
// the same rule as scripts/check-health.sh.
const https = require('https');
const log = require('SyntheticsLogger');

function getJson(url) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { headers: { Accept: 'application/json' } }, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        if (res.statusCode !== 200) {
          reject(new Error(`HTTP ${res.statusCode}: ${body.slice(0, 300)}`));
          return;
        }
        try {
          resolve(JSON.parse(body));
        } catch (e) {
          reject(new Error(`Health did not return JSON: ${body.slice(0, 300)}`));
        }
      });
    });
    req.setTimeout(20000, () => req.destroy(new Error('Timed out after 20 s')));
    req.on('error', reject);
  });
}

exports.handler = async () => {
  const url = process.env.HEALTH_URL;
  if (!url) throw new Error('HEALTH_URL is not set');
  const health = await getJson(url);
  log.info(`Health: ${JSON.stringify(health)}`);
  if (health.Status !== 'OK') {
    throw new Error(`Health is ${health.Status}: last sync ${health.LastSyncStatus}, `
      + `${health.HoursSinceSuccess} h since last success, active snapshot ${health.ActiveSnapshotId}`);
  }
  return 'OK';
};
